// ============================================================================
// HELPER: NEXT SUNDAY 10:00 AM - 1:00 PM IST CALCULATOR
// ============================================================================
interface SundaySessionInfo {
  targetDate: Date;
  formattedDate: string;
  shortDate: string;
  timeRange: string;
}

function getNextSundayMorningSession(nowInput?: Date): SundaySessionInfo {
  const now = nowInput ? new Date(nowInput.getTime()) : new Date();
  const day = now.getDay(); // 0 = Sunday
  const target = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 10, 0, 0, 0);

  if (day === 0) {
    // If it's Sunday past 11:00 AM, roll over to next Sunday
    const cutoff = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 11, 0, 0, 0);
    if (now.getTime() >= cutoff.getTime()) {
      target.setDate(target.getDate() + 7);
    }
  } else {
    const daysUntilSunday = (7 - day) % 7;
    target.setDate(target.getDate() + daysUntilSunday);
  }

  const dayNum = target.getDate();
  const suffix =
    dayNum > 3 && dayNum < 21
      ? 'th'
      : dayNum % 10 === 1
      ? 'st'
      : dayNum % 10 === 2
      ? 'nd'
      : dayNum % 10 === 3
      ? 'rd'
      : 'th';

  const monthFull = target.toLocaleString('en-US', { month: 'long' });
  const monthShort = target.toLocaleString('en-US', { month: 'short' });
  const year = target.getFullYear();

  return {
    targetDate: target,
    formattedDate: `Sunday, ${dayNum}${suffix} ${monthFull} ${year}`,
    shortDate: `Sun, ${dayNum} ${monthShort}`,
    timeRange: '10:00 AM – 1:00 PM IST'
  };
}

function getAccountingBreakdown(totalInr: number) {
  if (totalInr === 1) {
    return { base: 1, cgst: 0, sgst: 0, gstTotal: 0, total: 1 };
  }
  const base = totalInr === 499 ? 422.88 : totalInr === 99 ? 83.90 : Math.round((totalInr / 1.18) * 100) / 100;
  const cgst = Math.round(base * 0.09 * 100) / 100;
  const sgst = Math.round(base * 0.09 * 100) / 100;
  const gstTotal = Math.round((cgst + sgst) * 100) / 100;
  return { base, cgst, sgst, gstTotal, total: totalInr };
}

// ============================================================================
// 3D INTERACTIVE TILT CARD COMPONENT (GPU-ACCELERATED PRESERVE-3D)
// ============================================================================
interface Card3DProps {
  children: React.ReactNode;
  className?: string;
  intensity?: number;
  glowColor?: string;
}

const Interactive3DCard: React.FC<Card3DProps> = ({
  children,
  className = '',
  intensity = 14,
  glowColor = 'rgba(139, 92, 246, 0.35)'
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [hovered, setHovered] = useState(false);

  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const springCfg = { damping: 22, stiffness: 220 };
  const rotateX = useSpring(useTransform(mouseY, [-0.5, 0.5], [intensity, -intensity]), springCfg);
  const rotateY = useSpring(useTransform(mouseX, [-0.5, 0.5], [-intensity, intensity]), springCfg);

  const glareBg = useTransform(
    [mouseX, mouseY],
    ([lx, ly]) =>
      `radial-gradient(circle at ${((lx as number) + 0.5) * 100}% ${((ly as number) + 0.5) * 100}%, ${glowColor}, transparent 60%)`
  );

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const nx = (e.clientX - rect.left) / rect.width - 0.5;
    const ny = (e.clientY - rect.top) / rect.height - 0.5;
    mouseX.set(nx);
    mouseY.set(ny);
  };

  const handleMouseLeave = () => {
    setHovered(false);
    mouseX.set(0);
    mouseY.set(0);
  };

  return (
    <div style={{ perspective: '1200px' }} className="h-full">
      <motion.div
        ref={cardRef}
        onMouseMove={handleMouseMove}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={handleMouseLeave}
        style={{
          rotateX,
          rotateY,
          transformStyle: 'preserve-3d'
        }}
        className={`relative h-full transition-shadow duration-300 ${className}`}
      >
        <motion.div
          className="pointer-events-none absolute inset-0 rounded-3xl z-10"
          style={{
            background: glareBg,
            opacity: hovered ? 1 : 0,
            transition: 'opacity 0.25s ease'
          }}
        />
        <div style={{ transform: 'translateZ(28px)', transformStyle: 'preserve-3d' }} className="relative z-20 h-full">
          {children}
        </div>
      </motion.div>
    </div>
  );
};

